import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D0.4 · 评测、安全与工程基线","description":"Hearth D0.4 开发增量：可重复的 12 任务评测、明确的安全边界，以及可运行的类型检查、测试、CI 和 fake executor。","frontmatter":{"title":"D0.4 · 评测、安全与工程基线","description":"Hearth D0.4 开发增量：可重复的 12 任务评测、明确的安全边界，以及可运行的类型检查、测试、CI 和 fake executor。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-0/d0-4.md","filePath":"delivery/stage-0/d0-4.md","lastUpdated":null}'),r={name:"delivery/stage-0/d0-4.md"};function s(h,a,o,d,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 0 · D0.4 · 4 / 4</p><h1 id="d0-4-·-评测、安全与工程基线" tabindex="-1">D0.4 · 评测、安全与工程基线 <a class="header-anchor" href="#d0-4-·-评测、安全与工程基线" aria-label="Permalink to &quot;D0.4 · 评测、安全与工程基线&quot;">​</a></h1><p class="lead">让后续每一个增量从第一天起都能被重复验证、被安全约束，并在 CI 中阻止契约与数据回归。</p><p class="page-meta">STAGE 0 · D0.4 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>可重复的 12 任务评测、明确的安全边界，以及可运行的类型检查、测试、CI 和 fake executor。</div><div><strong>完成门槛</strong>评测可在本地重复运行；高风险动作必须有审批路径；CI 能阻止 schema 和契约回归；fake executor 能驱动完整 UI；没有真实外部副作用。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>可重复的 12 任务评测、明确的安全边界，以及可运行的类型检查、测试、CI 和 fake executor。</p><p>Stage 0 的产出是产品真相与实现契约。没有真实任务、可点击原型和可重复评测，后续开发会把假设当成事实。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>一个空仓库、可记录的真实工作样本，以及一位愿意持续反馈的首位用户。</li><li>允许观察全人工流程与直接使用 Codex 的基线，不要求系统已经存在。</li><li>本阶段不接入真实发送、支付、删除或系统设置修改。</li><li>D0.3 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-12-任务评测-runner" tabindex="-1">01 · 12 任务评测 runner <a class="header-anchor" href="#_01-·-12-任务评测-runner" aria-label="Permalink to &quot;01 · 12 任务评测 runner&quot;">​</a></h3><p>评测器读取任务包，执行基线或候选实现，按产物结构、事实依据、格式、人工复核和成本评分。记录失败分类和可恢复性；同一任务、同一评分器才能横向比较。</p><h3 id="_02-·-威胁模型与审批矩阵" tabindex="-1">02 · 威胁模型与审批矩阵 <a class="header-anchor" href="#_02-·-威胁模型与审批矩阵" aria-label="Permalink to &quot;02 · 威胁模型与审批矩阵&quot;">​</a></h3><p>列出资产、攻击面、信任边界和最坏后果，至少覆盖提示词注入、越权工具调用、秘密泄露、重复副作用和伪造完成。按风险等级定义审批、Effect Preview、禁止动作和人工接管。</p><h3 id="_03-·-工程骨架与-ci" tabindex="-1">03 · 工程骨架与 CI <a class="header-anchor" href="#_03-·-工程骨架与-ci" aria-label="Permalink to &quot;03 · 工程骨架与 CI&quot;">​</a></h3><p>建立 monorepo、lint、类型检查、单元/契约/集成测试、ADR 模板和文档目录。CI 至少拦住 schema 回归、契约破坏、危险动作无审批、迁移不兼容和未登记状态。</p><h3 id="_04-·-fake-executor-与观测字段" tabindex="-1">04 · Fake executor 与观测字段 <a class="header-anchor" href="#_04-·-fake-executor-与观测字段" aria-label="Permalink to &quot;04 · Fake executor 与观测字段&quot;">​</a></h3><p>fake executor 驱动没有真实副作用的完整 UI 流程，并能注入超时、失败、未知状态和恢复。统一定义 trace、Token、成本、延迟、人工分钟、打断次数和失败类型字段，后续阶段不得另建口径。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>packages/core/src/schema</code> — 领域实体、状态机与失败分类</li><li><code>packages/eventlog</code> — Event Log、投影与 migration</li><li><code>packages/evals</code> — 任务集、runner、评分与人工复核</li><li><code>apps/web</code> — 今日、需要你、产物、设置与任务详情原型</li><li><code>fixtures/tasks</code> — 真实任务样本与失败样本</li><li><code>docs/adr</code> — Build vs Integrate、事件模型与前端投影决策</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>Event</code></td><td>id、type、schemaVersion、occurredAt、actor、subject、causationId、correlationId、payload；只追加，不能覆盖历史。</td></tr><tr><td><code>TaskCardProjection</code></td><td>taskId、title、state、primaryAction、reason、lastEventAt、artifacts、budget；页面不读取数据库字段。</td></tr><tr><td><code>ExecutorEvent</code></td><td>标准化事件、产物引用、structResult、validation、failureClass、recoverable；执行器不直接写主库。</td></tr><tr><td><code>Approval</code></td><td>effectPreview、scope、expiresAt、decision、idempotencyKey；审批绑定真实动作和参数。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:smoke：12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个任务可重复跑分</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev：打开桌面与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 390px</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 手机宽度原型</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-0/d0-4.html">D0.4 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：12 任务评测 runner、威胁模型与审批矩阵、工程骨架与 CI、Fake executor 与观测字段。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“原型状态无法映射”。页面必须显示“页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。”，然后按“补齐状态映射、更新契约测试，再重新演示原路径。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：评测可在本地重复运行；高风险动作必须有审批路径；CI 能阻止 schema 和契约回归；fake executor 能驱动完整 UI；没有真实外部副作用。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>12 任务评测 runner</li><li>威胁模型与审批矩阵</li><li>Monorepo/CI/测试基线</li><li>fake executor 演示记录</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 评测可在本地重复运行；高风险动作必须有审批路径；CI 能阻止 schema 和契约回归；fake executor 能驱动完整 UI；没有真实外部副作用。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>原型状态无法映射</td><td>页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。</td><td>补齐状态映射、更新契约测试，再重新演示原路径。</td></tr><tr><td>真实任务无法验收</td><td>任务保留在候选池，标注原因，不进入开发承诺。</td><td>补清输入、产物或验收方式，或换一个真实任务。</td></tr><tr><td>基线不可比较</td><td>该任务不进入评测集，避免用失真的数据证明价值。</td><td>重新记录人工分钟、成功率、Token 与失败类型。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不先做完整内核再补界面。</li><li>不用文档完成度替代可点击原型与可重复评测。</li><li>不接入真实高风险外部副作用。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/design/">项目设计与取舍</a></li><li><a href="/hearth-os/reference/checklists.html">默认清单</a></li><li><a href="/hearth-os/architecture/domain-model.html">领域模型与协议</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>返回 <a href="/hearth-os/delivery/stage-0.html">Stage 0 · 定义与原型</a>，确认全部退出条件后进入 <a href="/hearth-os/delivery/stage-1.html">Stage 1</a>。</p>`,42)])])}const u=e(r,[["render",s]]);export{k as __pageData,u as default};
